window.__votdWeek && window.__votdWeek({"week":"2029-04-09","reading":"Doctrine and Covenants 29","days":[{"d":"2029-04-09","ref":"D&C 29:5","b":"D&C","c":29,"v":5,"he":"הָרִימוּ לְבַבְכֶם וְשִׂמְחוּ כִּי בְתוֹכְכֶם אָנֹכִי וּמֵלִיץ אֲנִי לָכֶם לִפְנֵי הָאָב וּרְצוֹנוֹ הַטּוֹב לָתֵת לָכֶם אֶת־הַמַּלְכוּת׃","en":"Lift up your hearts and be glad, for I am in your midst, and am your advocate with the Father; and it is his good will to give you the kingdom."},{"d":"2029-04-10","ref":"D&C 29:9","b":"D&C","c":29,"v":9,"he":"כִּי קׇרְבָה הַשָּׁעָה וְהַיּוֹם מְמַהֵר לָבוֹא בַּאֲשֶׁר הָאָרֶץ בָּשְׁלָה וְכׇל־זֵדִים וְעֹשֵׂי רִשְׁעָה יִהְיוּ כְקַשׁ וּשְׂרַפְתִּים נְאֻם יְהוָה צְבָאוֹת וְלֹא תִהְיֶה רִשְׁעָה עַל הָאָרֶץ׃","en":"For the hour is nigh and the day soon at hand when the earth is ripe; and all the proud and they that do wickedly shall be as stubble; and I will burn them up, saith the Lord of Hosts, that wickedness shall not be upon the earth;"},{"d":"2029-04-11","ref":"D&C 29:11","b":"D&C","c":29,"v":11,"he":"כִּי אֶגָּלֶה מִן הַשָּׁמַיִם בְּכֹחַ וּבְכָבוֹד גָּדוֹל עִם כׇּל צְבָאָם וְאֶשְׁכֹּן בְּצֶדֶק עִם אֲנָשִׁים עַל הָאָרֶץ אֶלֶף שָׁנִים וְהָרְשָׁעִים לֹא יַעֲמֹדוּ׃","en":"For I will reveal myself from heaven with power and great glory, with all the hosts thereof, and dwell in righteousness with men on earth a thousand years, and the wicked shall not stand."},{"d":"2029-04-12","ref":"D&C 29:16","b":"D&C","c":29,"v":16,"he":"וּבָרָד כָּבֵד יִשָּׁלַח לְהַשְׁמִיד אֶת־יְבוּל הָאָרֶץ׃","en":"And there shall be a great hailstorm sent forth to destroy the crops of the earth."},{"d":"2029-04-13","ref":"D&C 29:28","b":"D&C","c":29,"v":28,"he":"לָכֵן אֹמַר לָהֶם סוּרוּ מִמֶּנִּי אֲרוּרִים אֶל אֵשׁ עוֹלָם הַמּוּכָנָה לַשָּׂטָן וּמַלְאָכָיו׃","en":"Wherefore I will say unto them—Depart from me, ye cursed, into everlasting fire, prepared for the devil and his angels."},{"d":"2029-04-14","ref":"D&C 29:40","b":"D&C","c":29,"v":40,"he":"לָכֵן נִסָּה הַשָּׂטָן אֶת־אָדָם וַיֹּאכַל מִן הַפְּרִי אֲשֶׁר אָסַרְתִּי וַיַּעֲבֹר אֶת־הַמִּצְוָה בַּאֲשֶׁר נִכְנַע לִרְצוֹן הַשָּׂטָן כִּי נָתַן לַמַּסָּה׃","en":"Wherefore, it came to pass that the devil tempted Adam, and he partook of the forbidden fruit and transgressed the commandment, wherein he became subject to the will of the devil, because he yielded unto temptation."},{"d":"2029-04-15","ref":"D&C 29:45","b":"D&C","c":29,"v":45,"he":"כִּי אֹהֲבִים הֵם חֹשֶׁךְ מֵאוֹר וּמַעֲשֵׂיהֶם רָעִים וּמְקַבְּלִים שְׂכָרָם מֵאֲשֶׁר בָּחֲרוּ לִשְׁמֹעַ׃","en":"For they love darkness rather than light, and their deeds are evil, and they receive their wages of whom they list to obey."}]});
